import{_ as t,o as s,c as a,ag as i}from"./chunks/framework.rlnGb3AE.js";const u=JSON.parse('{"title":"Configuration","description":"","frontmatter":{},"headers":[],"relativePath":"shuttle-access/configuration.md","filePath":"shuttle-access/configuration.md"}'),d={name:"shuttle-access/configuration.md"};function n(o,e,c,r,h,l){return s(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h1><p>All Shuttle.Access-specific settings live under <code>Shuttle:Access</code> in <code>appsettings.json</code>. JWT issuer and OAuth provider configuration have their own page — see <a href="/shuttle-access/json-web-tokens.html">JSON Web Tokens</a> — and the <a href="/shuttle-access/consistency.html">Consistency</a> page covers <code>Shuttle:Recall:EventProcessing:ImmediateConsistency</code> in detail. This page covers everything else.</p><p>Connection strings (<code>ConnectionStrings:Access</code>, <code>ConnectionStrings:azure</code>) and <code>Shuttle:Hopper</code> (queue transports and message routes — see the <a href="/shuttle-access/docker.html">Docker</a> and <a href="/shuttle-access/docker-compose.html">Docker Compose</a> guides for example values) follow standard <code>Shuttle.Hopper</code> configuration.</p><h2 id="shuttle-access-—-shared" tabindex="-1"><code>Shuttle:Access</code> — shared <a class="header-anchor" href="#shuttle-access-—-shared" aria-label="Permalink to &quot;`Shuttle:Access` — shared&quot;">​</a></h2><p>Bound by <code>AccessOptions</code>, used by both <code>Shuttle.Access.WebApi</code> and <code>Shuttle.Access.Server</code>.</p><table tabindex="0"><thead><tr><th>Property</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>SystemTenantId</code></td><td><code>c3ee3908-716b-48df-abda-33b49e09be97</code></td><td>Id of the built-in system tenant</td></tr><tr><td><code>SystemTenantName</code></td><td><code>System</code></td><td>Name of the built-in system tenant</td></tr><tr><td><code>SystemAdministratorIdentityName</code></td><td><code>shuttle-admin</code></td><td>Identity name seeded on first run</td></tr><tr><td><code>SystemAdministratorPassword</code></td><td><code>shuttle-admin</code></td><td>Password seeded on first run — <strong>change this</strong></td></tr><tr><td><code>SessionDuration</code></td><td><code>08:00:00</code></td><td>How long a session is valid for once registered</td></tr><tr><td><code>SessionRenewalTolerance</code></td><td><code>00:15:00</code></td><td>Window before expiry within which a session is renewed rather than re-issued</td></tr></tbody></table><h2 id="shuttle-access-api-—-shuttle-access-webapi" tabindex="-1"><code>Shuttle:Access:Api</code> — <code>Shuttle.Access.WebApi</code> <a class="header-anchor" href="#shuttle-access-api-—-shuttle-access-webapi" aria-label="Permalink to &quot;`Shuttle:Access:Api` — `Shuttle.Access.WebApi`&quot;">​</a></h2><p>Bound by <code>ApiOptions</code>.</p><table tabindex="0"><thead><tr><th>Property</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>AllowPasswordAuthentication</code></td><td><code>true</code></td><td>Whether <code>POST /v1/sessions</code> accepts an identity name/password body</td></tr><tr><td><code>OAuthRegisterUnknownIdentities</code></td><td><code>true</code></td><td>Whether a successful OAuth sign-in registers a new identity when none exists</td></tr><tr><td><code>ExtensionFolder</code></td><td><code>./.extension</code></td><td>Folder Shuttle.Access.WebApi looks in for OAuth provider SVG icons (<code>{ExtensionFolder}/OAuth/{provider}.svg</code>)</td></tr></tbody></table><h2 id="shuttle-access-authorization" tabindex="-1"><code>Shuttle:Access:Authorization</code> <a class="header-anchor" href="#shuttle-access-authorization" aria-label="Permalink to &quot;`Shuttle:Access:Authorization`&quot;">​</a></h2><p>This one section is bound by two different option classes, depending on which package reads it:</p><ul><li><code>Shuttle.Access.AspNetCore</code>&#39;s <code>AccessAuthorizationOptions</code> — used by <strong>every</strong> application, including the web API itself, to secure its own endpoints (see <a href="/shuttle-access/home.html#securing-an-endpoint">Securing an endpoint</a>).</li><li><code>Shuttle.Access.WebApi</code>&#39;s <code>AccessAuthenticationOptions</code> — used <strong>only</strong> by the web API, because it is the sole deployment that validates issuers and tokens (see <a href="/shuttle-access/sessions.html">Sessions</a>).</li></ul><p>The properties each binds are disjoint, so a single section safely serves both:</p><table tabindex="0"><thead><tr><th>Property</th><th>Bound by</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>BaseAddress</code></td><td>every app except <code>Shuttle.Access.WebApi</code></td><td><em>(empty)</em></td><td>Address of the <code>Shuttle.Access.WebApi</code> deployment that resolves the caller&#39;s session</td></tr><tr><td><code>Realm</code></td><td>every app</td><td><code>API</code></td><td>Realm reported on a <code>401</code> challenge</td></tr><tr><td><code>InsecureModeEnabled</code></td><td><code>Shuttle.Access.WebApi</code> only</td><td><code>false</code></td><td>Bypasses signature validation — never enable in production</td></tr><tr><td><code>Issuers</code></td><td><code>Shuttle.Access.WebApi</code> only</td><td><code>[]</code></td><td>Accepted JWT issuers — see <a href="/shuttle-access/json-web-tokens.html">JSON Web Tokens</a></td></tr></tbody></table><h2 id="shuttle-access-server-—-shuttle-access-server" tabindex="-1"><code>Shuttle:Access:Server</code> — <code>Shuttle.Access.Server</code> <a class="header-anchor" href="#shuttle-access-server-—-shuttle-access-server" aria-label="Permalink to &quot;`Shuttle:Access:Server` — `Shuttle.Access.Server`&quot;">​</a></h2><p>Bound by <code>ServerOptions</code>.</p><table tabindex="0"><thead><tr><th>Property</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>MonitorKeepAliveInterval</code></td><td><code>00:00:15</code></td><td>Interval at which the server&#39;s keep-alive heartbeat runs</td></tr><tr><td><code>Timeout</code></td><td><code>00:02:00</code></td><td>Keep-alive timeout before the server is considered unresponsive</td></tr></tbody></table><h2 id="shuttle-access-sqlserver" tabindex="-1"><code>Shuttle:Access:SqlServer</code> <a class="header-anchor" href="#shuttle-access-sqlserver" aria-label="Permalink to &quot;`Shuttle:Access:SqlServer`&quot;">​</a></h2><p>Bound by <code>AccessSqlServerOptions</code>.</p><table tabindex="0"><thead><tr><th>Property</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>ConnectionString</code></td><td><em>(empty)</em></td><td>Overrides <code>ConnectionStrings:Access</code> when set</td></tr><tr><td><code>CommandTimeout</code></td><td><code>00:00:30</code></td><td>SQL command timeout</td></tr></tbody></table><h2 id="shuttle-access-client-—-shuttle-access-restclient" tabindex="-1"><code>Shuttle:Access:Client</code> — <code>Shuttle.Access.RestClient</code> <a class="header-anchor" href="#shuttle-access-client-—-shuttle-access-restclient" aria-label="Permalink to &quot;`Shuttle:Access:Client` — `Shuttle.Access.RestClient`&quot;">​</a></h2><p>Bound by <code>AccessClientOptions</code>. Used by any application that calls <code>Shuttle.Access.WebApi</code> as itself — see <a href="/shuttle-access/sessions.html#calling-shuttle-access-as-yourself">Calling Shuttle.Access as yourself</a>.</p><table tabindex="0"><thead><tr><th>Property</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>BaseAddress</code></td><td><em>(empty)</em></td><td>Address of the <code>Shuttle.Access.WebApi</code> deployment to call</td></tr><tr><td><code>RenewToleranceTimeSpan</code></td><td><code>00:05:00</code></td><td>Window before session expiry within which the client renews it</td></tr></tbody></table><h3 id="shuttle-access-client-passwordauthenticationinterceptor" tabindex="-1"><code>Shuttle:Access:Client:PasswordAuthenticationInterceptor</code> <a class="header-anchor" href="#shuttle-access-client-passwordauthenticationinterceptor" aria-label="Permalink to &quot;`Shuttle:Access:Client:PasswordAuthenticationInterceptor`&quot;">​</a></h3><p>Bound by <code>PasswordAuthenticationInterceptorOptions</code>, when using <code>UsePasswordAuthenticationProvider(...)</code>.</p><table tabindex="0"><thead><tr><th>Property</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>IdentityName</code></td><td><em>(empty)</em></td><td>Identity used to authenticate this application as itself</td></tr><tr><td><code>Password</code></td><td><em>(empty)</em></td><td>Password for <code>IdentityName</code></td></tr><tr><td><code>TenantId</code></td><td><em>(none)</em></td><td>Tenant to authenticate against, if not the system tenant</td></tr></tbody></table><h2 id="putting-it-together" tabindex="-1">Putting it together <a class="header-anchor" href="#putting-it-together" aria-label="Permalink to &quot;Putting it together&quot;">​</a></h2><p>A minimal <code>Shuttle.Access.WebApi</code> configuration, combining several of the sections above with the consistency toggle and connection strings:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;ConnectionStrings&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;Access&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;server=database;database=Access;user id=sa;password=Pass!000;TrustServerCertificate=true&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;azure&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;UseDevelopmentStorage=true;DevelopmentStorageProxyUri=http://azurite&quot;</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  },</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;Shuttle&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;Access&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;Api&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">        &quot;AllowPasswordAuthentication&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">        &quot;OAuthRegisterUnknownIdentities&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">      }</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    },</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;Recall&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;EventProcessing&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">        &quot;ImmediateConsistency&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">          &quot;Enabled&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        }</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">      }</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    }</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>See the <a href="/shuttle-access/docker.html">Docker</a> and <a href="/shuttle-access/docker-compose.html">Docker Compose</a> guides for full, runnable <code>server-appsettings.json</code>/<code>webapi-appsettings.json</code> examples.</p>',30)])])}const k=t(d,[["render",n]]);export{u as __pageData,k as default};
